ist<CementProduct>> = _products.asStateFlow()\n180:     override fun getCurrentProducts(): List<CementProduct> = _products.value\n181: \n182:     override fun getParties(): List<Party> = initialParties\n183: \n184:     override fun getTransactionsFlow(): Flow<List<StockTransaction>> = _transactions.asStateFlow()\n185:     override fun getCurrentTransactions(): List<StockTransaction> = _transactions.value\n186: \n187:     override fun getDashboardTelemetry(): Flow<DashboardTelemetry> {\n188:         return _products.map { products ->\n189:             val totalBags = products.sumOf { it.currentStockBags }\n190:             val totalMt = (totalBags * 50.0) / 1000.0\n191: \n192:             val brandShares = products.map {\n193:                 val pct = if (totalBags > 0) (it.currentStockBags.toFloat() / totalBags.toFloat()) else 0f\n194:                 BrandShare(brandName = it.brandName, percentage = pct)\n195:             }\n196: \n197:             DashboardTelemetry(\n198:                 totalStoredBags = totalBags,\n199:                 totalMetricTons = totalMt,\n200:                 inwardDayBags = 1200,\n201:                 inwardDayMt = 60.0,\n202:                 dispatchedBags = 850,\n203:                 dispatchedMt = 42.5,\n204:                 pendingSlipsCount = 1,\n205:                 netTallyBags = 350,\n206:                 brandDistribution = brandShares\n207:             )\n208:         }\n209:     }\n210: \n211:     override suspend fun getTransactionBySlipNo(slipNo: String): StockTransaction? {\n212:         mutex.withLock {\n213:             return _transactions.value.find { it.slipNo.equals(slipNo, ignoreCase = true) }\n214:         }\n215:     }\n216: \n217:     override suspend fun getLastSlip(): StockTransaction? {\n218:         mutex.withLock {\n219:             return _transactions.value.firstOrNull()\n220:         }\n221:     }\n222: \n223:     override suspend fun recordDispatch(transaction: StockTransaction): Result<StockTransaction> {\n224:         mutex.withLock {\n225:             val currentList = _products.value.toMutableList()\n226: \n227:             // Validate inventory sufficiency\n228:             for (item in transaction.items) {\n229:                 val index = currentList.indexOfFirst { it.id == item.productId }\n230:                 if (index == -1) {\n231:                     return Result.failure(IllegalArgumentException(\"Product ${item.productName} not found\"))\n232:                 }\n233:                 val product = currentList[index]\n234:                 if (product.currentStockBags < item.quantityBags) {\n235:                     return Result.failure(\n236:                         IllegalStateException(\"Insufficient stock for ${product.name}. Available: ${product.currentStockBags} bags, Requested: ${item.quantityBags} bags\")\n237:                     )\n238:                 }\n239:             }\n240: \n241:             // Deduct stock\n242:             for (item in transaction.items) {\n243:                 val index = currentList.indexOfFirst { it.id == item.productId }\n244:                 val product = currentList[index]\n245:                 currentList[index] = product.copy(\n246:                     currentStockBags = product.currentStockBags - item.quantityBags\n247:                 )\n248:             }\n249: \n250:             _products.value = currentList\n251:             val updatedTx = _transactions.value.toMutableList()\n252:             updatedTx.add(0, transaction)\n253:             _transactions.value = updatedTx\n254: \n255:             return Result.success(transaction)\n256:         }\n257:     }\n258: \n259:     override suspend fun recordStockIn(\n260:         productId: String,\n261:         bags: Int,\n262:         batchNo: String,\n263:         bayLocation: String\n264:     ): Result<Unit> {\n265:         if (bags <= 0) {\n266:             return Result.failure(IllegalArgumentException(\"Stock-in quantity must be positive\"))\n267:         }\n268: \n269:         mutex.withLock {\n270:             val currentList = _products.value.toMutableList()\n271:             val index = currentList.indexOfFirst { it.id == productId }\n272:             if (index == -1) {\n273:                 return Result.failure(IllegalArgumentException(\"Product ID $productId not found\"))\n274:             }\n275: \n276:             val product = currentList[index]\n277:             currentList[index] = product.copy(\n278:                 currentStockBags = product.currentStockBags + bags,\n279:                 batchNo = if (batchNo.isNotBlank()) batchNo else product.batchNo,\n280:                 bayLocation = if (bayLocation.isNotBlank()) bayLocation else product.bayLocation\n281:             )\n282:             _products.value = currentList\n283: \n284:             val newSlipNo = \"GRN-${System.currentTimeMillis() % 100000}\"\n285:             val newTx = StockTransaction(\n286:                 id = \"tx_${System.currentTimeMillis()}\",\n287:                 slipNo = newSlipNo,\n288:                 type = TransactionType.INWARD,\n289:                 timestamp = System.currentTimeMillis(),\n290:                 partyName = \"${product.brandName} Factory Delivery\",\n291:                 vehicleNo = \"FACTORY-UNLOAD\",\n292:                 driverName = \"Depot Inward\",\n293:                 driverPhone = \"-\",\n294:                 challanNo = \"INW-$newSlipNo\",\n295:                 ewbNo = \"-\",\n296:                 destinationSite = \"Godown #4 - ${product.bayLocation}\",\n297:                 totalBags = bags,\n298:                 totalMetricTons = (bags * 50.0) / 1000.0,\n299:                 totalAmount = bags * product.defaultRatePerBag,\n300:                 items = listOf(\n301:                     StockTransactionItem(\n302:                         productId = product.id,\n303:                         productName = product.name,\n304:                         quantityBags = bags,\n305:                 